{
  "rules": [
    {
      "category": "algorithmic_rent_setting",
      "title": "San Francisco algorithmic rent-setting ban",
      "requirement": "Landlords are prohibited from using algorithmic devices or revenue management software that use non-public competitor data to set, recommend, or advise on rents or occupancy levels. Additionally, it is unlawful to sell, license, or provide such devices to San Francisco landlords.",
      "requirement_es": "Se prohíbe a los propietarios utilizar dispositivos algorítmicos o programas de gestión de ingresos que utilicen datos no públicos de competidores para fijar, recomendar o asesorar sobre los alquileres o los niveles de ocupación. Además, es ilegal vender, licenciar o proporcionar dichos dispositivos a propietarios de San Francisco.",
      "key_value": {
        "label": "Civil penalty per violation",
        "value": "up to $1,000"
      },
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [
        {
          "description": "Products used for the purpose of establishing rent or income limits in accordance with affordable housing program guidelines of a local, state, or federal government.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "rent_subsidized",
                "operator": "==",
                "value": true,
                "note": "product used for establishing rent or income limits in accordance with affordable housing program guidelines"
              }
            ]
          }
        },
        {
          "description": "Reports that publish existing rental data in an aggregated manner but do not recommend rents or occupancy levels for future leases.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        }
      ],
      "effective_date": "2024-10-14",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": null
      },
      "penalty": "Civil penalties of up to $1,000 per violation, injunctive relief, restitution/return of illegal profits, and reasonable attorney's fees and costs. Each separate month a violation continues and each separate residential dwelling unit constitutes a separate violation.",
      "source_citation": "S.F. Admin. Code § 37.10C(a)-(d)",
      "quote": {
        "chunk": "c5",
        "start_words": "It shall be unlawful for a landlord",
        "end_words": "separate and distinct violation."
      },
      "confidence": 0.95
    }
  ]
}
